/**
 * generated by stackra gen from src/config/env.config.ts (server fields), src/config/edge.config.ts
 * (redirects, redirectCacheSeconds, notFoundLog), src/config/csp.config.ts and runway.yaml
 * (aliases) — do not edit
 * Purpose: the Cloudflare Worker entry: validates the server env once, redirects an alias host to
 *          the canonical domain, resolves SEO redirects before routing, hands every other request
 *          to the React Router server build with `{ env, ctx, container }` as the load context,
 *          sets the CSP header, and records HTML 404s for the experience `seo` module after the
 *          response is sent.
 * Boundary: config classes are resolved from the container the Worker boots once, never read as
 *           statics; the CSP baseline is @stackra/csp's and the config only adds sources.
 * Runtime: worker
 */
import { createRequestHandler } from "react-router";
import { bootstrapWorker } from "@stackra/app/worker";
import { contentSecurityPolicy } from "@stackra/csp";
import { serverEnv } from "#stackra/env";
import { publicClients } from "#stackra/clients.server";
import { Experience } from "#stackra/clients";
import { wiring } from "#stackra/wiring";
import { CspConfig } from "#src/config/csp.config";
import { EdgeConfig } from "#src/config/edge.config";
import { WebApp } from "#src/web.app";

const requestHandler = createRequestHandler(
  () => import("virtual:react-router/server-build"),
  import.meta.env.MODE,
);
const container = await bootstrapWorker(WebApp, { wiring });

/** Only navigations are redirected or logged; asset and data requests pass straight through. */
function isHtmlNavigation(request: Request): boolean {
  return request.method === "GET" && (request.headers.get("accept") ?? "").includes("text/html");
}

export default {
  async fetch(request, rawEnv, ctx) {
    const env = serverEnv(rawEnv); // a missing var fails the first request with a typed error
    const edge = container.resolve(EdgeConfig);
    const url = new URL(request.url);
    const canonical = new URL(env.siteUrl);
    if (url.host !== canonical.host && !url.host.startsWith("localhost")) {
      return Response.redirect(new URL(url.pathname + url.search, canonical).toString(), 301);
    }
    const clients = publicClients(env);

    if (isHtmlNavigation(request) && edge.lookupRedirects) {
      const cache = caches.default;
      const key = new Request(`${url.origin}/__redirect${url.pathname}`);
      let cached = await cache.match(key);
      if (!cached) {
        const redirect = await clients.query(Experience.queries.ResolveRedirect, {
          host: url.host,
          path: url.pathname,
        });
        const maxAge = `max-age=${edge.redirectCacheSeconds}`;
        cached = Response.json(redirect, { headers: { "Cache-Control": maxAge } });
        ctx.waitUntil(cache.put(key, cached.clone()));
      }
      const redirect = (await cached.json()) as { to: string; status: 301 | 302 } | null;
      if (redirect) return Response.redirect(new URL(redirect.to, url).toString(), redirect.status);
    }

    const response = await requestHandler(request, { env, ctx, container });
    response.headers.set(
      "Content-Security-Policy",
      contentSecurityPolicy(container.resolve(CspConfig), { connect: [env.apiUrl] }),
    );

    if (edge.notFoundLog && response.status === 404 && isHtmlNavigation(request)) {
      const referrer = request.headers.get("referer") ?? undefined;
      ctx.waitUntil(
        clients.queue(Experience.actions.RecordNotFound, {
          host: url.host,
          path: url.pathname,
          referrer,
        }),
      );
    }
    return response;
  },
} satisfies ExportedHandler<Env>;
